#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("diamond.in");
    std::ofstream out("diamond.out");
    int n, tolerance;
    in >> n >> tolerance;
    std::vector<int> sizes(n);
    for (int &size : sizes) in >> size;
    std::sort(sizes.begin(), sizes.end());
    int left = 0, best = 0;
    for (int right = 0; right < n; ++right) {
        while (sizes[right] - sizes[left] > tolerance) ++left;
        best = std::max(best, right - left + 1);
    }
    out << best << '\n';
}
