#include <cstdint>
#include <fstream>
#include <set>
#include <string>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("bcs.in");
    std::ofstream out("bcs.out");
    int n, k;
    in >> n >> k;
    std::vector<std::string> target(n);
    for (std::string &row : target) in >> row;
    std::uint64_t targetMask = 0;
    for (int r = 0; r < n; ++r)
        for (int c = 0; c < n; ++c)
            if (target[r][c] == '#') targetMask |= std::uint64_t{1} << (r * n + c);
    std::vector<std::set<std::uint64_t>> placements(k);
    for (int piece = 0; piece < k; ++piece) {
        std::vector<std::pair<int, int>> cells;
        for (int r = 0; r < n; ++r) {
            std::string row;
            in >> row;
            for (int c = 0; c < n; ++c) if (row[c] == '#') cells.push_back({r, c});
        }
        for (int dr = 1 - n; dr < n; ++dr) {
            for (int dc = 1 - n; dc < n; ++dc) {
                bool valid = true;
                std::uint64_t mask = 0;
                for (const auto &[r, c] : cells) {
                    const int rr = r + dr, cc = c + dc;
                    if (rr < 0 || rr >= n || cc < 0 || cc >= n || target[rr][cc] != '#') {
                        valid = false;
                        break;
                    }
                    mask |= std::uint64_t{1} << (rr * n + cc);
                }
                if (valid) placements[piece].insert(mask);
            }
        }
    }
    for (int i = 0; i < k; ++i) {
        for (int j = i + 1; j < k; ++j) {
            for (std::uint64_t first : placements[i]) {
                if (placements[j].count(targetMask ^ first)) {
                    out << i + 1 << ' ' << j + 1 << '\n';
                    return 0;
                }
            }
        }
    }
}
