int main() {
    std::ifstream in("reduce.in");
    std::ofstream out("reduce.out");
    int n;
    in >> n;
    std::vector<std::pair<long long, long long>> points(n);
    for (auto &[x, y] : points) in >> x >> y;
    int minX = 0, maxX = 0, minY = 0, maxY = 0;
    for (int i = 1; i < n; ++i) {
        if (points[i].first < points[minX].first) minX = i;
        if (points[i].first > points[maxX].first) maxX = i;
        if (points[i].second < points[minY].second) minY = i;
        if (points[i].second > points[maxY].second) maxY = i;
    }
    const std::set<int> candidates{minX, maxX, minY, maxY};
    long long best = std::numeric_limits<long long>::max();
    for (int removed : candidates) {
        long long loX = 40001, hiX = 0, loY = 40001, hiY = 0;
        for (int i = 0; i < n; ++i) {
            if (i == removed) continue;
            loX = std::min(loX, points[i].first);
            hiX = std::max(hiX, points[i].first);
            loY = std::min(loY, points[i].second);
            hiY = std::max(hiY, points[i].second);
        }
        best = std::min(best, (hiX - loX) * (hiY - loY));
    }
    out << best << '\n';
}
